import{T as e,f as t,u as n}from"./runtime-core.esm-bundler-BMtdqVnY.js";import{t as r}from"./index-C3esoFcu.js";var i={},a={class:`p-4 lg:p-6 max-w-4xl mx-auto`};function o(r,i){return e(),n(`div`,a,[...i[0]||=[t(`<h1 class="text-2xl font-display font-bold mb-2">Help &amp; Documentation</h1><p class="text-sm text-gray-400 mb-6">Quick reference for MeshSat Hub features and workflows.</p><div class="space-y-4"><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">Getting Started</h2><div class="space-y-2 text-[12px] text-gray-400 leading-relaxed"><p>MeshSat Hub is the cloud-side management platform for MeshSat field devices. It receives satellite messages (Iridium SBD, Astrocast, Globalstar), manages device fleets, and provides routing, alerting, and situational awareness.</p><p><strong class="text-gray-300">1.</strong> Register a device in <strong class="text-gray-300">Devices</strong> — enter the IMEI and select the modem type (RockBLOCK, Astrocast, or Globalstar).</p><p><strong class="text-gray-300">2.</strong> Configure your webhook — point your Ground Control (Rock7) or Astrocast account&#39;s HTTP callback to <code class="text-gray-300 bg-gray-800 px-1 rounded">https://your-hub/api/webhook/rockblock</code>.</p><p><strong class="text-gray-300">3.</strong> Set up routing rules in <strong class="text-gray-300">Routing</strong> to forward incoming messages to notifications, webhooks, MQTT, TAK, or APRS.</p></div></div><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">Pages</h2><div class="space-y-2 text-[12px] text-gray-400"><div class="font-display text-[10px] text-gray-500 uppercase tracking-wider mt-1">Operations</div><div><strong class="text-gray-300">Dashboard</strong> — KPI overview: hub health, device count, message throughput, credit balance, constellation status, safety alerts, and recent messages.</div><div><strong class="text-gray-300">Map</strong> — Leaflet map showing device positions from GPS reports and Iridium geolocation.</div><div><strong class="text-gray-300">Devices</strong> — Register, view, and manage satellite devices. Each device has a detail page with keys, config versions, and position history.</div><div><strong class="text-gray-300">Messages</strong> — View all MO (Mobile Originated) and MT (Mobile Terminated) messages. Send MT messages to devices via Iridium or SMS via Twilio.</div><div class="font-display text-[10px] text-gray-500 uppercase tracking-wider mt-3">Safety</div><div><strong class="text-gray-300">Escalation</strong> — View active alerts and configure escalation chains (notification steps with delays and channels).</div><div><strong class="text-gray-300">Deadman</strong> — Dead man&#39;s switch: alert when a device stops checking in within a configured interval.</div><div><strong class="text-gray-300">Geofences</strong> — Draw geographic boundaries on the map. Triggers alerts when devices enter or leave a zone.</div><div><strong class="text-gray-300">Notifications</strong> — Configure per-device notification preferences (Apprise URLs, event types, enable/disable).</div><div class="font-display text-[10px] text-gray-500 uppercase tracking-wider mt-3">Channels</div><div><strong class="text-gray-300">Email</strong> — PGP-encrypted email gateway. Add contacts with public keys, send/receive encrypted email over satellite.</div><div><strong class="text-gray-300">Routing</strong> — Configurable any-to-any message routing with 7 destination handlers (SMS, email, webhook, notification, MQTT, TAK, APRS). Includes route flow diagram and test tool.</div><div><strong class="text-gray-300">Webhooks</strong> — Outbound webhook dispatcher. Forward device events to external HTTP endpoints with delivery logs and retry.</div><div class="font-display text-[10px] text-gray-500 uppercase tracking-wider mt-3">Infrastructure</div><div><strong class="text-gray-300">Cluster</strong> — MariaDB Galera cluster health: node status, sync state, remediation actions (force resync, flush tables, desynced node).</div><div><strong class="text-gray-300">Network</strong> — Satellite constellation status (Iridium, Astrocast, Globalstar) and MPTCP concentrator configuration.</div><div><strong class="text-gray-300">Topology</strong> — Reticulum transport layer: hub identity, transport interfaces, routing table, relay statistics.</div><div><strong class="text-gray-300">OTA</strong> — Over-the-air firmware updates for field devices via hawkBit. Register targets, create rollouts, monitor deployments.</div><div><strong class="text-gray-300">Backup</strong> — Export all devices, messages, routes, and configuration as JSON. Import to restore or migrate.</div><div><strong class="text-gray-300">Settings</strong> — System health, Reticulum identity, network services, sensor payload codecs, API documentation links.</div><div class="font-display text-[10px] text-gray-500 uppercase tracking-wider mt-3">Admin (owner only)</div><div><strong class="text-gray-300">Users</strong> — Invite, manage roles (owner/operator/viewer), and delete users.</div><div><strong class="text-gray-300">API Keys</strong> — Create scoped API keys with role, device restriction, and expiry. Keys use the <code class="text-gray-300 bg-gray-800 px-1 rounded">meshsat_</code> prefix.</div><div><strong class="text-gray-300">Audit</strong> — Tamper-evident SHA-256 hash-chain audit log. Every login, webhook, and admin action is recorded with chain verification.</div></div></div><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">Webhook Setup</h2><div class="space-y-2 text-[12px] text-gray-400 leading-relaxed"><p><strong class="text-gray-300">RockBLOCK (Iridium SBD)</strong> — In your Rock7 Core account, set the delivery URL to <code class="text-gray-300 bg-gray-800 px-1 rounded">https://your-hub/api/webhook/rockblock</code>. Set a shared secret and configure it as <code class="text-gray-300 bg-gray-800 px-1 rounded">HUB_ROCKBLOCK_SECRET</code> in Hub&#39;s config.</p><p><strong class="text-gray-300">Twilio (SMS)</strong> — Configure your Twilio phone number&#39;s webhook URL to <code class="text-gray-300 bg-gray-800 px-1 rounded">https://your-hub/api/webhook/sms</code>. Set <code class="text-gray-300 bg-gray-800 px-1 rounded">HUB_TWILIO_*</code> env vars for outbound SMS.</p><p><strong class="text-gray-300">Astrocast</strong> — Set the Astronode API callback to <code class="text-gray-300 bg-gray-800 px-1 rounded">https://your-hub/api/webhook/astrocast</code>.</p><p><strong class="text-gray-300">Globalstar</strong> — Set the SPOT/Globalstar callback to <code class="text-gray-300 bg-gray-800 px-1 rounded">https://your-hub/api/webhook/globalstar</code>.</p></div></div><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">Routing Rules</h2><div class="space-y-2 text-[12px] text-gray-400 leading-relaxed"><p>Routing rules define how incoming messages are processed and forwarded. Each rule has a source (satellite channel), destination (handler), optional filter, and enabled/disabled state.</p><p><strong class="text-gray-300">Sources</strong> — Any satellite constellation (Iridium, Astrocast, Globalstar) or &quot;all&quot; for catch-all rules.</p><p><strong class="text-gray-300">Destinations</strong> — SMS, Email, Webhook, Notification (Apprise/ntfy), MQTT topic, TAK/CoT server, or APRS-IS.</p><p><strong class="text-gray-300">Filters</strong> — Match on device IMEI, message content, or channel. Empty filter matches all messages.</p><p><strong class="text-gray-300">Default routes</strong> — Hub ships with 5 default routes (APRS, MQTT, Notifications, TAK, Webhooks) that can be enabled/disabled.</p><p>Use the <strong class="text-gray-300">Route Tester</strong> to simulate a message and see which rules would fire.</p></div></div><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">SOS &amp; Dead Man&#39;s Switch</h2><div class="space-y-2 text-[12px] text-gray-400 leading-relaxed"><p><strong class="text-gray-300">SOS Detection</strong> — Hub monitors incoming messages for SOS keywords. When detected, an alert is triggered and the escalation chain is activated.</p><p><strong class="text-gray-300">Dead Man&#39;s Switch</strong> — Configure a check-in interval per device. If the device doesn&#39;t send a message (MO or position) within the interval, an alert fires after the grace period expires. Snooze is available for planned maintenance.</p><p><strong class="text-gray-300">Escalation Chains</strong> — Define multi-step notification sequences with delays. Example: SMS immediately, then email after 5 minutes, then phone call after 15 minutes.</p></div></div><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">API &amp; Authentication</h2><div class="space-y-2 text-[12px] text-gray-400 leading-relaxed"><p>Hub exposes a REST API on all <code class="text-gray-300 bg-gray-800 px-1 rounded">/api/*</code> endpoints. Authenticate with a Bearer token (API key or auth token).</p><p><strong class="text-gray-300">API Keys</strong> — Create scoped keys in the Admin section. Keys can be restricted to a specific role (viewer/operator/owner), device IMEI, and expiry date.</p><p><strong class="text-gray-300">Swagger/OpenAPI</strong> — API documentation is available at <code class="text-gray-300 bg-gray-800 px-1 rounded">/api/swagger/</code> when the Hub is running.</p><p><strong class="text-gray-300">RBAC</strong> — Three roles: <strong>Viewer</strong> (read-only), <strong>Operator</strong> (send messages, manage devices), <strong>Owner</strong> (full admin access including users, keys, audit).</p></div></div><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">Troubleshooting</h2><div class="space-y-2 text-[12px] text-gray-400 leading-relaxed"><p><strong class="text-gray-300">Webhook not receiving messages</strong> — Check that the Ground Control callback URL is correct and that the shared secret matches. View the Audit log for <code class="text-gray-300 bg-gray-800 px-1 rounded">message_received</code> events.</p><p><strong class="text-gray-300">MT send fails</strong> — Verify the device IMEI is registered and the Cloudloop API key is configured. Check credits balance on the Dashboard.</p><p><strong class="text-gray-300">Cluster unhealthy</strong> — Check the Cluster page for node status. If <code class="text-gray-300 bg-gray-800 px-1 rounded">cluster_size=1</code>, the Galera cluster is split. Use remediation actions to resync.</p><p><strong class="text-gray-300">Login fails</strong> — API Token login uses the <code class="text-gray-300 bg-gray-800 px-1 rounded">HUB_AUTH_TOKEN</code> env var. Email login requires OIDC to be configured.</p><p><strong class="text-gray-300">Messages not routing</strong> — Check the Routing page for active routes. Use the Route Tester to verify which rules match. Ensure the destination handler is configured (e.g., Twilio for SMS, Apprise URL for notifications).</p></div></div></div><div class="bg-tactical-surface rounded-lg border border-tactical-border p-4 mt-4"><h2 class="text-sm font-display font-semibold text-gray-200 uppercase tracking-wider mb-2">Additional Resources</h2><div class="flex flex-wrap gap-x-6 gap-y-2 text-sm"><a href="/api/docs" target="_blank" class="text-teal-400 hover:text-teal-300">Swagger API Docs</a><a href="/api/docs/swagger.json" target="_blank" class="text-gray-400 hover:text-gray-300">OpenAPI JSON</a><a href="/api/docs/swagger.yaml" target="_blank" class="text-gray-400 hover:text-gray-300">OpenAPI YAML</a></div></div><p class="text-[10px] text-gray-600 mt-6 text-center">MeshSat Hub v1.1</p>`,5)]])}var s=r(i,[[`render`,o]]);export{s as default};